using VisualRelay.Core.Tasks;

namespace VisualRelay.Tests;

public sealed class TaskTemplatesTests
{
    [Fact]
    public void Parse_Frontmatter_ExtractsNameTitleAndBody()
    {
        var content = "---\nname: Fancy\ntitle: Do it\n---\nBody line.\n";
        var result = TaskTemplates.Parse("fancy", content, TaskTemplateSource.BuiltIn);

        Assert.Equal("Fancy", result.Name);
        Assert.Equal("Do it", result.Title);
        Assert.Equal("Body line.\n", result.Body);
    }

    [Fact]
    public void Parse_NoFrontmatter_WholeContentIsBody_NameFallsBackToId()
    {
        var content = "# Just a heading\n\nSome body text.\n";
        var result = TaskTemplates.Parse("my-id", content, TaskTemplateSource.User);

        Assert.Equal("my-id", result.Name);
        Assert.Equal(string.Empty, result.Title);
        Assert.Equal(content, result.Body);
    }

    [Fact]
    public void Parse_CrLf_NormalizedBeforeParsing()
    {
        var content = "---\r\nname: Fancy\r\ntitle: Do it\r\n---\r\nBody line.\r\n";
        var result = TaskTemplates.Parse("fancy", content, TaskTemplateSource.BuiltIn);

        Assert.Equal("Fancy", result.Name);
        Assert.Equal("Do it", result.Title);
        Assert.Equal("Body line.\n", result.Body);
    }

    [Fact]
    public void Parse_UnknownFrontmatterKeys_Ignored()
    {
        var content = "---\nname: X\ncolor: blue\nunknown: y\n---\nBody.\n";
        var result = TaskTemplates.Parse("x", content, TaskTemplateSource.User);

        Assert.Equal("X", result.Name);
        Assert.Equal("Body.\n", result.Body);
    }

    [Fact]
    public void Parse_UnclosedFrontmatter_TreatedAsBody()
    {
        var content = "---\nname: X\nno close";
        var result = TaskTemplates.Parse("my-id", content, TaskTemplateSource.User);

        Assert.Equal("my-id", result.Name);
        Assert.Equal(string.Empty, result.Title);
        Assert.Equal(content, result.Body);
    }

    [Fact]
    public void Load_BuiltIns_BlankFirstThenSpeedUp()
    {
        var templates = TaskTemplates.Load("/nonexistent/user", "/nonexistent/repo");

        Assert.Equal(2, templates.Count);

        // [0] is Blank.
        Assert.Equal("blank", templates[0].Id);
        Assert.Equal("Blank", templates[0].Name);
        Assert.Equal(string.Empty, templates[0].Title);
        Assert.Equal(string.Empty, templates[0].Body);
        Assert.Equal(TaskTemplateSource.BuiltIn, templates[0].Source);

        // [1] is speed-up.
        Assert.Equal("speed-up-automated-tests", templates[1].Id);
        Assert.Equal("Create Tasks to Speed Up Automated Tests", templates[1].Name);
        Assert.Equal("Speed up automated tests", templates[1].Title);
        Assert.Equal(TaskTemplateSource.BuiltIn, templates[1].Source);
    }

    [Fact]
    public void Load_UserOverridesBuiltIn_RepoOverridesUser()
    {
        using var userDir = new TempDirectory();
        using var repoDir = new TempDirectory();

        Directory.CreateDirectory(userDir.Path);
        File.WriteAllText(Path.Combine(userDir.Path, "blank.md"), "---\nname: Blank\n---\nUSER");

        var templates = TaskTemplates.Load(userDir.Path, "/nonexistent/repo");
        var blank = templates[0];
        Assert.Equal("blank", blank.Id);
        Assert.Equal("USER\n", blank.Body);
        Assert.Equal(TaskTemplateSource.User, blank.Source);

        // Now add a repo override.
        Directory.CreateDirectory(repoDir.Path);
        File.WriteAllText(Path.Combine(repoDir.Path, "blank.md"), "---\nname: Blank\n---\nREPO");

        templates = TaskTemplates.Load(userDir.Path, repoDir.Path);
        blank = templates[0];
        Assert.Equal("blank", blank.Id);
        Assert.Equal("REPO\n", blank.Body);
        Assert.Equal(TaskTemplateSource.Repo, blank.Source);

        // Blank stays index 0 both times.
        Assert.Equal("blank", templates[0].Id);
    }

    [Fact]
    public void Load_NewIdsFromBothLayers_AppearSortedByName()
    {
        using var userDir = new TempDirectory();
        using var repoDir = new TempDirectory();

        Directory.CreateDirectory(userDir.Path);
        File.WriteAllText(Path.Combine(userDir.Path, "zebra.md"), "---\nname: Zebra\n---\nz");

        Directory.CreateDirectory(repoDir.Path);
        File.WriteAllText(Path.Combine(repoDir.Path, "alpha-custom.md"), "---\nname: Alpha Custom\n---\na");

        var templates = TaskTemplates.Load(userDir.Path, repoDir.Path);

        // Blank first, then by Name, then by Id.
        Assert.Equal("blank", templates[0].Id);
        Assert.True(templates.Any(t => t.Id == "alpha-custom"));
        Assert.True(templates.Any(t => t.Id == "zebra"));
    }

    [Fact]
    public void Load_UnreadableEntrySkipped()
    {
        using var userDir = new TempDirectory();

        Directory.CreateDirectory(userDir.Path);
        // Create a directory named broken.md — reading it as a file will throw.
        Directory.CreateDirectory(Path.Combine(userDir.Path, "broken.md"));
        File.WriteAllText(Path.Combine(userDir.Path, "good.md"), "---\nname: Good\n---\nok");

        var templates = TaskTemplates.Load(userDir.Path, "/nonexistent/repo");
        Assert.DoesNotContain(templates, t => t.Id == "broken");
        Assert.Contains(templates, t => t.Id == "good");
    }

    [Fact]
    public void SpeedUpTemplate_PinsLoadBearingContent()
    {
        var templates = TaskTemplates.Load("/nonexistent/user", "/nonexistent/repo");
        var speedUp = templates.Single(t => t.Id == "speed-up-automated-tests");

        Assert.Contains("- test time dropped from 80s to 60s, saving 20s", speedUp.Body);
        Assert.Contains("Never delete, disable, skip, or weaken a test", speedUp.Body);
        Assert.DoesNotContain("dotnet", speedUp.Body);
    }

    private sealed class TempDirectory : IDisposable
    {
        public string Path { get; } = System.IO.Path.Combine(
            System.IO.Path.GetTempPath(), "vr-task-templates-tests", Guid.NewGuid().ToString("N"));

        public TempDirectory()
        {
            Directory.CreateDirectory(Path);
        }

        public void Dispose()
        {
            try { Directory.Delete(Path, recursive: true); } catch { /* best effort */ }
        }
    }
}

